```javascript
// index.js
'use strict';

const { EventEmitter } = require('events');
const { Readable, Writable, Transform } = require('stream');

class Pipeline extends EventEmitter {
  constructor(options = {}) {
    super();
    this.stages = [];
    this.concurrency = options.concurrency || 1;
    this.timeout = options.timeout || 30000;
    this.retryCount = options.retryCount || 3;
    this.metrics = {
      processed: 0,
      failed: 0,
      totalTime: 0
    };
  }

  pipe(fn, options = {}) {
    this.stages.push({ fn, options });
    return this;
  }

  compose(...fns) {
    fns.forEach(fn => this.pipe(fn));
    return this;
  }

  async process(data) {
    const startTime = Date.now();
    let result = data;

    for (const stage of this.stages) {
      try {
        result = await this._executeWithTimeout(stage.fn, result);
        this.metrics.processed++;
      } catch (error) {
        this.metrics.failed++;
        if (stage.options.continueOnError) continue;
        throw error;
      }
    }

    this.metrics.totalTime += Date.now() - startTime;
    this.emit('processed', result);
    return result;
  }

  async processBatch(items) {
    const results = [];
    const chunks = this._chunkArray(items, this.concurrency);

    for (const chunk of chunks) {
      const chunkResults = await Promise.allSettled(
        chunk.map(item => this.process(item))
      );
      results.push(...chunkResults);
    }

    return results;
  }

  createTransformStream() {
    const pipeline = this;
    return new Transform({
      objectMode: true,
      async transform(chunk, encoding, callback) {
        try {
          const result = await pipeline.process(chunk);
          callback(null, result);
        } catch (error) {
          callback(error);
        }
      }
    });
  }

  _executeWithTimeout(fn, data) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => {
        reject(new Error('Pipeline stage timeout'));
      }, this.timeout);

      Promise.resolve(fn(data))
        .then(result => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch(error => {
          clearTimeout(timer);
          reject(error);
        });
    });
  }

  _chunkArray(array, size) {
    const chunks = [];
    for (let i = 0; i < array.length; i += size) {
      chunks.push(array.slice(i, i + size));
    }
    return chunks;
  }

  getMetrics() {
    return { ...this.metrics };
  }

  reset() {
    this.stages = [];
    this.metrics = { processed: 0, failed: 0, totalTime: 0 };
    return this;
  }
}

class RetryablePipeline extends Pipeline {
  constructor(options = {}) {
    super(options);
    this.maxRetries = options.maxRetries || 3;
    this.backoffMs = options.backoffMs || 1000;
  }

  async process(data) {
    let lastError;

    for (let attempt = 0; attempt <= this.maxRetries; attempt++) {
      try {
        return await super.process(data);
      } catch (error) {
        lastError = error;
        if (attempt < this.maxRetries) {
          await this._delay(this.backoffMs * Math.pow(2, attempt));
        }
      }
    }

    throw lastError;
  }

  _delay(ms) {
    return new Promise(resolve => setTimeout(resolve, ms));
  }
}

class ParallelPipeline extends Pipeline {
  async processBatch(items) {
    const workers = Array(this.concurrency).fill(null).map(async () => {
      const results = [];
      while (items.length > 0) {
        const item = items.shift();
        if (item) {
          try {
            const result = await this.process(item);
            results.push({ status: 'fulfilled', value: result });
          } catch (error) {
            results.push({ status: 'rejected', reason: error });
          }
        }
      }
      return results;
    });

    const allResults = await Promise.all(workers);
    return allResults.flat();
  }
}

function createPipeline(options) {
  return new Pipeline(options);
}

function createRetryablePipeline(options) {
  return new RetryablePipeline(options);
}

function createParallelPipeline(options) {
  return new ParallelPipeline(options);
}

function composeAsync(...fns) {
  return async (input) => {
    let result = input;
    for (const fn of fns) {
      result = await fn(result);
    }
    return result;
  };
}

function pipeAsync(input, ...fns) {
  return composeAsync(...fns)(input);
}

function debounce(fn, delay) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    return new Promise((resolve) => {
      timeout = setTimeout(() => resolve(fn.apply(this, args)), delay);
    });
  };
}

function throttle(fn, limit) {
  let inThrottle = false;
  return function(...args) {
    if (!inThrottle) {
      inThrottle = true;
      const result = fn.apply(this, args);
      setTimeout(() => { inThrottle = false; }, limit);
      return result;
    }
  };
}

function memoize(fn, ttl = 60000) {
  const cache = new Map();
  return async function(...args) {
    const key = JSON.stringify(args);
    const cached = cache.get(key);

    if (cached && Date.now() - cached.timestamp < ttl) {
      return cached.value;
    }

    const value = await fn.apply(this, args);
    cache.set(key, { value, timestamp: Date.now() });
    return value;
  };
}

function withTimeout(fn, ms) {
  return function(...args) {
    return new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('Operation timed out')), ms);
      Promise.resolve(fn.apply(this, args))
        .then(result => {
          clearTimeout(timer);
          resolve(result);
        })
        .catch(error => {
          clearTimeout(timer);
          reject(error);
        });
    });
  };
}

function retry(fn, options = {}) {
  const { maxAttempts = 3, backoff = 1000 } = options;

  return async function(...args) {
    let lastError;

    for (let attempt = 0; attempt < maxAttempts; attempt++) {
      try {
        return await fn.apply(this, args);
      } catch (error) {
        lastError = error;
        if (attempt < maxAttempts - 1) {
          await new Promise(resolve => setTimeout(resolve, backoff * Math.pow(2, attempt)));
        }
      }
    }

    throw lastError;
  };
}

function batchProcessor(fn, options = {}) {
  const { batchSize = 10, concurrency = 1 } = options;
  let queue = [];
  let processing = false;

  return async function(item) {
    queue.push(item);

    if (!processing) {
      processing = true;
      await new Promise(resolve => setTimeout(resolve, 0));

      while (queue.length > 0) {
        const batch = queue.splice(0, batchSize);
        const promises = batch.map(i => fn(i));
        await Promise.all(promises);
      }

      processing = false;
    }
  };
}

