## DR Exercise Infrastructure Code

### 1. Provider Configuration

```hcl
# providers.tf
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  alias  = "primary"
  region = var.primary_region
  assume_role {
    role_arn = "arn:aws:iam::${var.primary_account_id}:role/${var.break_glass_role_name}"
  }
}

provider "aws" {
  alias  = "dr"
  region = var.dr_region
