### 3. IAM Shadow Admin User

```hcl
# iam-shadow-admin.tf
resource "aws_iam_user" "shadow_admin" {
  provider = aws.dr
  name     = "shadow-admin-${var.exercise_id}"
  tags = {
    Purpose    = "DR Exercise"
    ExerciseID = var.exercise_id
    Runbook    = "RB-2026-0023"
    Temporary  = "true"
  }
}

resource "aws_iam_access_key" "shadow_admin_key" {
  provider = aws.dr
  user     = aws_iam_user.shadow_admin.name
}

resource "aws_iam_user_policy_attachment" "admin_policy" {
  provider   = aws.dr
  user       = aws_iam_user.shadow_admin.name
  policy_arn = "arn:aws:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_user_policy" "shadow_admin_boundary" {
  provider = aws.dr
  name     = "shadow-admin-boundary"
  user     = aws_iam_user.shadow_admin.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Deny"
        Action = [
          "iam:DeleteUser",
          "iam:DeleteAccessKey",
          "organizations:*"
        ]
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.dr_region
          }
        }
      }
    ]
  })
}

# Store credentials in Secrets Manager for exercise
resource "aws_secretsmanager_secret" "shadow_admin_credentials" {
  provider    = aws.dr
  name        = "dr-exercise/shadow-admin-credentials"
  description = "Shadow admin credentials for DR exercise RB-2026-0023"

  tags = {
    Purpose    = "DR Exercise"
    ExerciseID = var.exercise_id
    Runbook    = "RB-2026-0023"
  }
}

resource "aws_secretsmanager_secret_version" "shadow_admin_credentials" {
  provider      = aws.dr
  secret_id     = aws_secretsmanager_secret.shadow_admin_credentials.id
  secret_string = jsonencode({
    access_key_id     = aws_iam_access_key.shadow_admin_key.id
    secret_access_key = aws_iam_access_key.shadow_admin_key.secret
    username          = aws_iam_user.shadow_admin.name
    created_at        = timestamp()
  })
}
