## 1. Version Bumping (vars/versionBump.groovy)

```groovy
#!/usr/bin/env groovy

/**
 * Automated version bumping based on conventional commits
 * Usage: versionBump()
 */
def call(Map config = [:]) {
    def defaultConfig = [
        versionFile: 'VERSION',
        packageJson: 'package.json',
        changelogFile: 'CHANGELOG.md',
        createTag: true,
        pushTag: true,
        bumpStrategy: 'auto' // auto, major, minor, patch
    ]

    def effectiveConfig = defaultConfig + config

    pipeline {
        agent any

        environment {
            CURRENT_VERSION = ''
            NEW_VERSION = ''
            BUMP_TYPE = ''
        }

        stages {
            stage('Determine Version Bump') {
                steps {
                    script {
                        def versionManager = new com.devops.VersionManager()

                        // Get current version
                        env.CURRENT_VERSION = versionManager.getCurrentVersion(effectiveConfig.versionFile)

                        // Analyze commits since last tag
                        def commits = versionManager.getCommitsSinceLastTag()

                        // Determine bump type based on conventional commits
                        env.BUMP_TYPE = versionManager.determineBumpType(commits, effectiveConfig.bumpStrategy)

                        // Calculate new version
                        env.NEW_VERSION = versionManager.bumpVersion(env.CURRENT_VERSION, env.BUMP_TYPE)

                        echo "Current version: ${env.CURRENT_VERSION}"
                        echo "Bump type: ${env.BUMP_TYPE}"
                        echo "New version: ${env.NEW_VERSION}"
                    }
                }
            }

            stage('Update Version Files') {
                steps {
                    script {
                        def versionManager = new com.devops.VersionManager()

                        // Update VERSION file
                        writeFile file: effectiveConfig.versionFile, text: env.NEW_VERSION

                        // Update package.json if exists
                        if (fileExists(effectiveConfig.packageJson)) {
                            versionManager.updatePackageJson(effectiveConfig.packageJson, env.NEW_VERSION)
                        }

                        // Generate changelog
                        versionManager.generateChangelog(
                            effectiveConfig.changelogFile, 
                            env.CURRENT_VERSION, 
                            env.NEW_VERSION
                        )
                    }
                }
            }

            stage('Commit and Tag') {
                when {
                    expression { effectiveConfig.createTag }
                }
                steps {
                    script {
                        def versionManager = new com.devops.VersionManager()

                        sh """
                            git config user.email "jenkins@devops.com"
                            git config user.name "Jenkins CI"
                            git add ${effectiveConfig.versionFile} ${effectiveConfig.packageJson} ${effectiveConfig.changelogFile}
                            git commit -m "chore(release): bump version to ${env.NEW_VERSION}"
                            git tag -a "v${env.NEW_VERSION}" -m "Release v${env.NEW_VERSION}"
                        """

                        if (effectiveConfig.pushTag) {
                            sh """
                                git push origin HEAD:${env.BRANCH_NAME}
                                git push origin v${env.NEW_VERSION}
                            """
                        }
                    }
                }
            }
        }
    }
}
```

## 2. Multi-Branch Pipeline (vars/multiBranchPipeline.groovy)

```groovy
#!/usr/bin/env groovy

/**
 * Multi-branch pipeline with environment-specific configurations
 * Usage: multiBranchPipeline()
 */
def call(Map config = [:]) {
    def defaultConfig = [
        environments: [
            development: [
                namespace: 'dev',
                cluster: 'dev-cluster',
                replicas: 1,
                resources: [
                    cpu: '100m',
                    memory: '128Mi'
                ]
            ],
            staging: [
                namespace: 'staging',
                cluster: 'staging-cluster',
                replicas: 2,
                resources: [
                    cpu: '250m',
                    memory: '256Mi'
                ]
            ],
            production: [
                namespace: 'prod',
                cluster: 'prod-cluster',
                replicas: 3,
                resources: [
                    cpu: '500m',
                    memory: '512Mi'
                ]
            ]
        ],
        branchMapping: [
            'develop': 'development',
            'staging': 'staging',
            'main': 'production',
            'master': 'production'
        ],
        defaultEnvironment: 'development'
    ]

    def effectiveConfig = defaultConfig + config

    // Determine environment based on branch
    def environment = effectiveConfig.branchMapping[env.BRANCH_NAME] ?: effectiveConfig.defaultEnvironment
    def envConfig = effectiveConfig.environments[environment]

    pipeline {
        agent any

        environment {
            DEPLOY_ENV = environment
            NAMESPACE = envConfig.namespace
            CLUSTER = envConfig.cluster
            REPLICAS = "${envConfig.replicas}"
            CPU_LIMIT = envConfig.resources.cpu
            MEMORY_LIMIT = envConfig.resources.memory
        }

        stages {
            stage('Checkout') {
                steps {
                    checkout scm
                }
            }

            stage('Environment Setup') {
                steps {
                    script {
                        echo "Deploying to ${environment} environment"
                        echo "Branch: ${env.BRANCH_NAME}"
                        echo "Namespace: ${envConfig.namespace}"

                        // Load environment-specific secrets
                        withCredentials([
                            string(credentialsId: "${environment}-config", variable: 'ENV_CONFIG'),
                            file(credentialsId: "${environment}-kubeconfig", variable: 'KUBECONFIG')
                        ]) {
                            // Setup environment
                            sh """
                                echo "${ENV_CONFIG}" > .env.${environment}
                                export KUBECONFIG=${KUBECONFIG}
                                kubectl config use-context ${envConfig.cluster}
                            """
                        }
                    }
                }
            }

            stage('Build') {
                steps {
                    script {
                        // Build with environment-specific settings
                        sh """
                            docker build \
                                --build-arg ENVIRONMENT=${environment} \
                                --build-arg VERSION=${env.BUILD_NUMBER} \
                                -t ${env.DOCKER_REGISTRY}/${env.APP_NAME}:${env.BUILD_NUMBER}-${environment} .
                        """
                    }
                }
            }

            stage('Test') {
                steps {
                    script {
                        // Run environment-specific tests
                        sh """
                            echo "Running tests for ${environment} environment"
                            # Add your test commands here
                        """
                    }
                }
            }

            stage('Deploy') {
                when {
                    expression { 
                        environment != 'production' || env.BRANCH_NAME == 'main' || env.BRANCH_NAME == 'master'
                    }
                }
                steps {
                    script {
                        helmDeploy(
                            environment: environment,
                            namespace: envConfig.namespace,
                            replicas: envConfig.replicas,
                            resources: envConfig.resources
                        )
                    }
                }
            }

            stage('Post-Deploy Verification') {
                steps {
                    script {
                        // Run environment-specific health checks
                        sh """
                            kubectl get pods -n ${envConfig.namespace}
                            kubectl get services -n ${envConfig.namespace}
                        """
                    }
                }
            }
        }

        post {
            always {
                cleanWs()
            }
            success {
                script {
                    if (environment == 'production') {
                        // Trigger canary analysis for production
                        canaryAnalysis(
                            namespace: envConfig.namespace,
                            duration: 10,
                            metrics: ['error_rate', 'latency', 'throughput']
                        )
                    }
                }
            }
        }
    }
}
