## 1. Webhook Server (Python/Flask)

```python
# webhook-server.py
from flask import Flask, request, jsonify
import requests
import json
import logging
import os
from kubernetes import client, config
import base64

app = Flask(__name__)
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

# Load Kubernetes config
try:
    config.load_incluster_config()
except:
    config.load_kube_config()

v1 = client.CoreV1Api()

class SecurityPolicyValidator:
    def __init__(self):
        self.allowed_registries = os.getenv('ALLOWED_REGISTRIES', 'gcr.io,registry.k8s.io').split(',')
        self.enforce_resource_limits = os.getenv('ENFORCE_RESOURCE_LIMITS', 'true').lower() == 'true'
        self.policy_evaluation_url = os.getenv('POLICY_EVALUATION_URL', 'https://policy.security.internal/evaluate')
        self.strict_mode = os.getenv('STRICT_MODE', 'true').lower() == 'true'

    def validate_pod_security_standards(self, pod_spec):
        """Validate against Pod Security Standards"""
        violations = []

        # Check privileged containers
        for container in pod_spec.get('containers', []):
            security_context = container.get('securityContext', {})

            # Check privileged mode
            if security_context.get('privileged', False):
                violations.append(f"Container {container['name']} runs in privileged mode")

            # Check allowPrivilegeEscalation
            if security_context.get('allowPrivilegeEscalation', True):
                violations.append(f"Container {container['name']} allows privilege escalation")

            # Check capabilities
            capabilities = security_context.get('capabilities', {}).get('add', [])
            if capabilities:
                violations.append(f"Container {container['name']} adds capabilities: {capabilities}")

            # Check host namespaces
            if pod_spec.get('hostNetwork', False):
                violations.append("Pod uses host network")
            if pod_spec.get('hostPID', False):
                violations.append("Pod uses host PID namespace")
            if pod_spec.get('hostIPC', False):
                violations.append("Pod uses host IPC namespace")

            # Check runAsNonRoot
            if not security_context.get('runAsNonRoot', False):
                violations.append(f"Container {container['name']} may run as root")

            # Check readOnlyRootFilesystem
            if not security_context.get('readOnlyRootFilesystem', False):
                violations.append(f"Container {container['name']} has writable root filesystem")

        return violations

    def validate_resource_limits(self, pod_spec):
        """Enforce resource limits"""
        violations = []

        for container in pod_spec.get('containers', []):
            resources = container.get('resources', {})
            limits = resources.get('limits', {})
            requests = resources.get('requests', {})

            if not limits:
                violations.append(f"Container {container['name']} has no resource limits")
            else:
                if 'memory' not in limits:
                    violations.append(f"Container {container['name']} has no memory limit")
                if 'cpu' not in limits:
                    violations.append(f"Container {container['name']} has no CPU limit")

            if not requests:
                violations.append(f"Container {container['name']} has no resource requests")

        return violations

    def validate_image_registries(self, pod_spec):
        """Check image registries"""
        violations = []

        for container in pod_spec.get('containers', []):
            image = container.get('image', '')
            registry = image.split('/')[0] if '/' in image else 'docker.io'

            if registry not in self.allowed_registries and not any(
                allowed in registry for allowed in self.allowed_registries
            ):
                violations.append(
                    f"Container {container['name']} uses image from unauthorized registry: {registry}"
                )

        # Check init containers
        for container in pod_spec.get('initContainers', []):
            image = container.get('image', '')
            registry = image.split('/')[0] if '/' in image else 'docker.io'

            if registry not in self.allowed_registries and not any(
                allowed in registry for allowed in self.allowed_registries
            ):
                violations.append(
                    f"Init container {container['name']} uses image from unauthorized registry: {registry}"
                )

        return violations

    def validate_service_account(self, pod_spec, namespace):
        """Verify service account restrictions"""
        violations = []

        service_account = pod_spec.get('serviceAccountName', 'default')

        # Check if default service account is used
        if service_account == 'default':
            violations.append("Pod uses default service account")

        # Check automountServiceAccountToken
        if pod_spec.get('automountServiceAccountToken', True):
            violations.append("Service account token is automatically mounted")

        # Check for specific restricted SAs
        restricted_sas = os.getenv('RESTRICTED_SERVICE_ACCOUNTS', '').split(',')
        if service_account in restricted_sas:
            violations.append(f"Pod uses restricted service account: {service_account}")

        return violations

    def validate_volumes(self, pod_spec, namespace):
        """Scan mounted volumes"""
        violations = []

        volumes = pod_spec.get('volumes', [])

        for volume in volumes:
            volume_name = volume.get('name', 'unknown')

            # Check hostPath volumes
            if 'hostPath' in volume:
                host_path = volume['hostPath'].get('path', '')
                violations.append(f"Volume {volume_name} mounts host path: {host_path}")

            # Check for sensitive host paths
            sensitive_paths = [
                '/var/run/docker.sock',
                '/proc',
                '/sys',
                '/etc/kubernetes',
                '/var/lib/kubelet'
            ]

            if 'hostPath' in volume:
                host_path = volume['hostPath'].get('path', '')
                if any(sensitive in host_path for sensitive in sensitive_paths):
                    violations.append(f"Volume {volume_name} mounts sensitive host path: {host_path}")

            # Check emptyDir with medium Memory
            if 'emptyDir' in volume:
                if volume['emptyDir'].get('medium') == 'Memory':
                    violations.append(f"Volume {volume_name} uses memory-backed emptyDir")

        # Check volume mounts in containers
        for container in pod_spec.get('containers', []):
            for volume_mount in container.get('volumeMounts', []):
                mount_path = volume_mount.get('mountPath', '')

                # Check for sensitive mount paths
                sensitive_mounts = [
                    '/etc/kubernetes',
                    '/var/run/secrets/kubernetes.io',
                    '/proc',
                    '/sys'
                ]

                if any(sensitive in mount_path for sensitive in sensitive_mounts):
                    violations.append(
                        f"Container {container['name']} mounts sensitive path: {mount_path}"
                    )

        return violations

    def extract_secrets_and_tokens(self, pod_spec, namespace):
        """Extract all secrets, tokens, and sensitive information from pod spec"""
        sensitive_data = {
            'environment_variables': [],
            'mounted_secrets': [],
            'service_account_tokens': [],
            'volumes': [],
            'security_contexts': []
        }

        # Extract environment variables (including secrets)
        for container in pod_spec.get('containers', []):
            env_vars = container.get('env', [])
            for env in env_vars:
                env_entry = {
                    'container': container['name'],
                    'name': env.get('name'),
                }

                if 'value' in env:
                    env_entry['value'] = env['value']
                    env_entry['type'] = 'plaintext'
                elif 'valueFrom' in env:
                    value_from = env['valueFrom']
                    if 'secretKeyRef' in value_from:
                        env_entry['type'] = 'secret_ref'
                        env_entry['secret_name'] = value_from['secretKeyRef'].get('name')
                        env_entry['secret_key'] = value_from['secretKeyRef'].get('key')
                    elif 'configMapKeyRef' in value_from:
                        env_entry['type'] = 'configmap_ref'
                        env_entry['configmap_name'] = value_from['configMapKeyRef'].get('name')
                        env_entry['configmap_key'] = value_from['configMapKeyRef'].get('key')
                    elif 'fieldRef' in value_from:
                        env_entry['type'] = 'field_ref'
                        env_entry['field_path'] = value_from['fieldRef'].get('fieldPath')

                sensitive_data['environment_variables'].append(env_entry)

            # Extract envFrom
            env_from = container.get('envFrom', [])
            for env_source in env_from:
                if 'secretRef' in env_source:
                    sensitive_data['environment_variables'].append({
                        'container': container['name'],
                        'type': 'secret

I'll create a comprehensive Terraform module for a production EKS cluster with all the requested components. This is a large module, so I'll organize it into multiple files for maintainability.

## Directory Structure

```
terraform-eks-production/
├── main.tf
├── variables.tf
├── outputs.tf
