## Root Configuration Files

### `providers.tf`
```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.5"
    }
  }

  backend "s3" {
    bucket         = "landing-zone-terraform-state"
    key            = "landing-zone/terraform.tfstate"
    region         = "us-east-1"
    encrypt        = true
    dynamodb_table = "landing-zone-terraform-locks"
  }
}

provider "aws" {
  region = var.aws_region

  default_tags {
    tags = {
      Environment = var.environment
      ManagedBy   = "Terraform"
      Project     = "LandingZone"
    }
  }
}

# Provider for management account operations
provider "aws" {
  alias  = "management"
  region = var.aws_region
}

# Provider for audit account
provider "aws" {
  alias  = "audit"
  region = var.aws_region

  assume_role {
    role_arn = "arn:aws:iam::${var.audit_account_id}:role/OrganizationAccountAccessRole"
  }
}

# Provider for log archive account
provider "aws" {
  alias  = "log_archive"
  region = var.aws_region

  assume_role {
    role_arn = "arn:aws:iam::${var.log_archive_account_id}:role/OrganizationAccountAccessRole"
  }
}
```

### `variables.tf`
```hcl
variable "aws_region" {
  description = "AWS region for primary deployment"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name"
  type        = string
  default     = "production"
}

variable "organization_name" {
  description = "Name of the AWS Organization"
  type        = string
  default     = "EnterpriseLandingZone"
}

variable "organization_featureset" {
  description = "Organization feature set (ALL or CONSOLIDATED_BILLING)"
  type        = string
  default     = "ALL"
}

variable "audit_account_email" {
  description = "Email for the audit account"
  type        = string
  sensitive   = true
}

variable "log_archive_account_email" {
  description = "Email for the log archive account"
  type        = string
  sensitive   = true
}

variable "audit_account_id" {
  description = "AWS Account ID for audit account"
  type        = string
}

variable "log_archive_account_id" {
  description = "AWS Account ID for log archive account"
  type        = string
}

variable "allowed_regions" {
  description = "List of allowed AWS regions"
