```

### `main.tf`
```hcl
# Create AWS Organization
module "organization" {
  source = "./modules/organization"

  organization_name       = var.organization_name
  featureset             = var.organization_featureset
  audit_account_email    = var.audit_account_email
  log_archive_account_email = var.log_archive_account_email
}

# Deploy Service Control Policies
module "scp" {
  source = "./modules/scp"

  depends_on = [module.organization]

  organization_id = module.organization.organization_id
  allowed_regions = var.allowed_regions
}

# Configure Control Tower
module "control_tower" {
  source = "./modules/control-tower"

  depends_on = [module.organization, module.scp]

  organization_id = module.organization.organization_id
  audit_account_id = var.audit_account_id
  log_archive_account_id = var.log_archive_account_id
}

# Deploy Security Services
module "security_services" {
  source = "./modules/security-services"

  providers = {
    aws.management  = aws.management
    aws.audit       = aws.audit
    aws.log_archive = aws.log_archive
  }

  depends_on = [module.control_tower]

  audit_account_id       = var.audit_account_id
  log_archive_account_id = var.log_archive_account_id
  allowed_regions        = var.allowed_regions
}

# Configure IAM Identity Center
module "identity_center" {
  source = "./modules/identity-center"

  depends_on = [module.organization]

  users  = var.identity_center_users
  groups = var.identity_center_groups
}

# Centralized Logging
module "logging" {
  source = "./modules/logging"

  providers = {
    aws.log_archive = aws.log_archive
  }

  depends_on = [module.organization]

  organization_id       = module.organization.organization_id
  log_archive_account_id = var.log_archive_account_id
}

# Compliance Auditor
module "compliance_auditor" {
  source = "./modules/compliance-auditor"

  providers = {
    aws.management = aws.management
  }

  depends_on = [module.security_services, module.logging]

  organization_id         = module.organization.organization_id
  audit_account_id        = var.audit_account_id
  notification_email      = var.compliance_notification_email
  member_account_ids      = [for account in module.organization.member_accounts : account.id]
}

# Create Member Accounts
module "member_accounts" {
  source = "./modules/member-account"

  for_each = { for account in var.member_accounts : account.name => account }

  depends_on = [module.organization, module.scp]

  account_name  = each.value.name
  account_email = each.value.email
  ou_name       = each.value.ou
  organization_id = module.organization.organization_id
}
```

### `outputs.tf`
```hcl
output "organization_id" {
  description = "AWS Organization ID"
  value       = module.organization.organization_id
}

output "organization_arn" {
  description = "AWS Organization ARN"
  value       = module.

